import {ONLINE_PROTOCOL,roomCode,validRoomCode,safeOnlineInput,applyOnlineState} from './online-protocol.js';
import {createFootballSimulation} from './football-simulation.js';
import {createOnlinePrediction} from './online-prediction.js';
export async function requestOnlineSeat(code,options={},fetcher=globalThis.fetch){const cleaned=roomCode(code);if(code&&!validRoomCode(cleaned))throw Error('请输入 8 位房间码');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);let response;try{response=await fetcher('/api/online/rooms'+(code?'/'+cleaned+'/join':''),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...options,protocol:ONLINE_PROTOCOL}),signal:controller.signal});}catch{throw Error('连接失败或超时，请检查网络后重试');}finally{clearTimeout(timer);}let data;try{data=await response.json();}catch{throw Error('联机服务暂未就绪，请稍后重试');}if(!response.ok)throw Error(data.error||'房间连接失败');return data;}
export function createOnlineSession(seat,{origin=globalThis.location?.origin,WebSocketClass=globalThis.WebSocket}={}){
 let socket=null,stopped=false,retry=null,heartbeat=null,attempt=0,firstResolve,firstReject,firstTimer,disconnectSince=0,desiredReady=false,inputSequence=0,lastSnapshotAt=0,requestSequence=0;const listeners=new Set(),pendingRequests=new Map();
 const session={...seat,connection:'connecting',error:'',room:null,packet:null,latency:0,jitter:0,request(message){if(session.connection!=='connected')return Promise.reject(Error('连接尚未就绪'));const id=++requestSequence;return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{pendingRequests.delete(id);reject(Error('请求超时，请重试'));},8000);pendingRequests.set(id,{resolve,reject,timer});if(!session.send({...message,id})){clearTimeout(timer);pendingRequests.delete(id);reject(Error('连接中断'));}});},setReady(value){desiredReady=!!value;session.send({type:'ready',ready:desiredReady});},subscribe(fn){listeners.add(fn);return()=>listeners.delete(fn);},send(message){if(socket?.readyState!==1)return false;socket.send(JSON.stringify(message));return true;},sendInput(input){const seq=++inputSequence;return session.send({type:'input',...safeOnlineInput(input),seq})?seq:0;},connect(){const promise=new Promise((resolve,reject)=>{firstResolve=resolve;firstReject=reject;});firstTimer=setTimeout(()=>{firstReject?.(Error('实时连接超时，请检查网络后重试'));session.close();},12000);open();return promise;},close(){stopped=true;clearTimeout(firstTimer);clearTimeout(retry);clearInterval(heartbeat);for(const request of pendingRequests.values()){clearTimeout(request.timer);request.reject(Error('连接已关闭'));}pendingRequests.clear();try{socket?.close(1000,'离开页面');}catch{}session.connection='closed';firstReject?.(Error(session.error||'连接已关闭'));firstResolve=firstReject=null;emit();},leave(){session.send({type:'leave'});session.close();}};
 function emit(){for(const fn of listeners)fn(session);}
 function open(){if(stopped)return;lastSnapshotAt=0;session.connection=attempt?'reconnecting':'connecting';emit();const url=new URL('/api/online/rooms/'+seat.code+'/socket',origin);url.protocol=url.protocol==='https:'?'wss:':'ws:';socket=new WebSocketClass(url.href,['arena-v2','seat.'+seat.token,...(desiredReady?['ready-v1']:[])]);const current=socket;
  socket.onmessage=event=>{if(current!==socket)return;let p;try{p=JSON.parse(event.data);}catch{return;}
   if(p.type==='welcome'){if(p.protocol!==ONLINE_PROTOCOL){session.error='联机版本已更新，请刷新网页';session.close();return;}clearTimeout(firstTimer);attempt=0;disconnectSince=0;session.connection='connected';session.error='';session.room=p.room;firstResolve?.(session);firstResolve=firstReject=null;clearInterval(heartbeat);heartbeat=setInterval(()=>session.send({type:'ping',at:Date.now()}),4000);session.send({type:'ping',at:Date.now()});session.send({type:'ready',ready:desiredReady});}
   if(p.type==='state'){const now=Date.now();if(lastSnapshotAt&&p.state?.phase==='playing'&&!p.state.paused)session.jitter+=.15*(Math.min(150,Math.abs(now-lastSnapshotAt-50))-session.jitter);lastSnapshotAt=now;if(p.room)session.room=p.room;const previous=session.packet;session.packet=p.state?{...p.state,teamSheets:p.state.teamSheets??previous?.teamSheets,discipline:p.state.discipline??previous?.discipline}:null;if(session.room?.ended)session.error=session.room.reason||'房间已结束';}
   if(p.type==='result'){const request=pendingRequests.get(p.id);if(request){pendingRequests.delete(p.id);clearTimeout(request.timer);if(p.ok)request.resolve(p);else request.reject(Error(p.error||'设置未能保存'));}}
   if(p.type==='pong'&&Number.isFinite(p.at))session.latency=Math.max(0,Math.round(Date.now()-p.at));emit();
  };
  socket.onerror=()=>{};
  socket.onclose=event=>{if(current!==socket||stopped)return;clearInterval(heartbeat);if([4001,4004,1008].includes(event.code)||session.room?.ended){session.error=event.reason||session.error||'房间已结束';session.close();return;}session.connection='reconnecting';session.error='连接中断，正在重连';emit();if(!disconnectSince)disconnectSince=Date.now();if(Date.now()-disconnectSince>55000){session.error='未能重新连接，请退出后重新创建房间';session.close();return;}retry=setTimeout(open,Math.min(5000,500*2**attempt++));};
 }
 return session;
}
export function createOnlineSimulation(session,settings={}){
 const roomRules=session.room?.rules||session.rules||settings.rules,simulation=createFootballSimulation({...settings,opponent:session.opponent,rules:roomRules,duration:roomRules?.duration||180,selections:session.room?.lineups||settings.selections,humanTeams:['home','away']}),state=simulation.state,team=session.team,prediction=createOnlinePrediction(team);state.controlledId=state.controlledIds[team];state.localTeam=team;state.paused=true;state.online=true;let blend=null,sendClock=0,lastInput='',closed=false,lastPacket=null,lastSequence=0;
 function receive(){const p=session.packet;if(p&&p!==lastPacket){lastPacket=p;const positions=state.players.map(p=>({x:p.x,z:p.z,yaw:p.yaw})),ball={...state.ball},oldPhase=state.phase;if(applyOnlineState(state,p,team)){prediction.receive(state,p.ack?.[team]||0);blend=oldPhase===state.phase&&state.phase==='playing'&&!state.paused?{age:0,duration:Math.min(.12,.045+(session.jitter||0)/2000),positions,ball,targets:state.players.map(p=>({x:p.x,z:p.z,yaw:p.yaw})),targetBall:{...state.ball}}:null;}}if(session.connection!=='connected'||!session.room?.started||session.room?.ended){state.paused=true;prediction.clear();}state.onlineStatus=session.connection;}
 const unsubscribe=session.subscribe(receive);receive();
 return{state,network:session,continuePeriod(){return session.request({type:'continue'});},setFormation(team,formation){return session.request({type:'formation',formation});},substitute(team,outId,inNumber){return session.request({type:'substitute',outId,inNumber});},ready(){session.send({type:'mode',mode:settings.controlMode||'semi'});session.send({type:'shot-kind',kind:settings.shotKind||'drive'});session.setReady(true);},dispose({keepSession=false}={}){if(closed)return;closed=true;unsubscribe();prediction.clear();if(!keepSession)session.leave();},update(dt,input={}){if(closed)return state;sendClock+=Math.min(dt,.1);const safe=safeOnlineInput(state.paused?{}:{...input,power:state.chargePower}),key=JSON.stringify(safe),interval=state.paused?.2:.05;if(sendClock>=interval||key!==lastInput&&(!lastInput||sendClock>=1/60-1e-6)){lastSequence=session.sendInput(safe)||0;sendClock=0;lastInput=key;}
  if(blend&&!state.paused){blend.age+=Math.min(dt,.1);const t=Math.min(1,blend.age/blend.duration);for(let i=0;i<22;i++){const p=state.players[i],a=blend.positions[i],b=blend.targets[i];if(p.id===state.controlledId)continue;p.x=a.x+(b.x-a.x)*t;p.z=a.z+(b.z-a.z)*t;p.yaw=a.yaw+Math.atan2(Math.sin(b.yaw-a.yaw),Math.cos(b.yaw-a.yaw))*t;}if(state.ball.ownerId!==state.controlledId&&Math.hypot(blend.ball.x-blend.targetBall.x,blend.ball.z-blend.targetBall.z)<6)for(const k of ['x','y','z'])state.ball[k]=blend.ball[k]+(blend.targetBall[k]-blend.ball[k])*t;if(t>=1)blend=null;}
  prediction.update(state,dt,safe,lastSequence);state.predictionSeconds=prediction.pendingSeconds;return state;},action(type,options={}){if(state.paused||!['playing','penalties'].includes(state.phase))return false;const sent=session.send({type:'action',action:type,direction:safeOnlineInput(options.direction),power:options.power});if(sent)prediction.animate(type,session.latency);return sent;},setPaused(value){session.sendInput({});session.send({type:'pause',paused:!!value});if(value){state.paused=true;prediction.clear();}},setControlMode(mode){state.controlMode=mode;session.send({type:'mode',mode});return mode;},setShotKind(kind){state.shotKind=kind;session.send({type:'shot-kind',kind});return kind;}};
}
